import { Type } from 'class-transformer';
import {
  IsInt,
  IsNotEmpty,
  IsString,
  IsUUID,
  Max,
  MaxLength,
  Min,
} from 'class-validator';

/** The upload page sends 5 MB chunks; the limit leaves headroom for clients. */
export const MAX_CHUNK_BYTES = 10 * 1024 * 1024;

/** 2,000 chunks of 5 MB caps a single upload at roughly 10 GB. */
export const MAX_CHUNKS = 2000;

export class UploadChunkDto {
  /** Generated by the client once per file, so parallel uploads never share chunk folders. */
  @IsUUID()
  uploadId: string;

  @IsString()
  @IsNotEmpty()
  @MaxLength(200)
  title: string;

  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(MAX_CHUNKS)
  chunkNumber: number;

  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(MAX_CHUNKS)
  totalChunks: number;
}
